<?php

declare(strict_types=1);

$database=require dirname(__DIR__).'/bootstrap/database.php';$pdo=$database->connection();$result=['projects_by_publication_status'=>[],'projects_by_progress'=>[],'published_projects'=>0,'project_members'=>0,'internal_members'=>0,'external_members'=>0,'linked_research_units'=>0];foreach($pdo->query('SELECT publication_status,COUNT(*) total FROM projects WHERE deleted_at IS NULL GROUP BY publication_status')as$r)$result['projects_by_publication_status'][$r['publication_status']]=(int)$r['total'];foreach($pdo->query('SELECT project_status,COUNT(*) total FROM projects WHERE deleted_at IS NULL GROUP BY project_status')as$r)$result['projects_by_progress'][$r['project_status']]=(int)$r['total'];$result['published_projects']=(int)$pdo->query('SELECT COUNT(*) FROM projects WHERE publication_status="published" AND published_at IS NOT NULL AND published_at<=NOW() AND deleted_at IS NULL')->fetchColumn();$result['project_members']=(int)$pdo->query('SELECT COUNT(*) FROM project_members')->fetchColumn();$result['internal_members']=(int)$pdo->query('SELECT COUNT(*) FROM project_members WHERE staff_id IS NOT NULL')->fetchColumn();$result['external_members']=(int)$pdo->query('SELECT COUNT(*) FROM project_members WHERE staff_id IS NULL AND external_member_name IS NOT NULL')->fetchColumn();$result['linked_research_units']=(int)$pdo->query('SELECT COUNT(*) FROM project_research_units')->fetchColumn();echo json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),PHP_EOL;
